def random_uuid():
    import uuid
    return str(uuid.uuid4())

def draw_pyramid(n):
    lines = []
    for i in range(n):
        lines.append(" " * (n - i - 1) + "*" * (2 * i + 1))
    return "\n".join(lines)

def draw_triangle(n):
    lines = []
    for i in range(1, n + 1):
        lines.append("*" * i)
    return "\n".join(lines)

def draw_reverse_triangle(n):
    lines = []
    for i in range(n, 0, -1):
        lines.append("*" * i)
    return "\n".join(lines)

def draw_hourglass(n):
    lines = []
    for i in range(n, 0, -1):
        lines.append(" " * (n - i) + "*" * (2 * i - 1))
    for i in range(2, n + 1):
        lines.append(" " * (n - i) + "*" * (2 * i - 1))
    return "\n".join(lines)

def draw_circle(r):
    lines = []
    for y in range(-r, r + 1):
        line = ""
        for x in range(-r, r + 1):
            if x*x + y*y <= r*r:
                line += "*"
            else:
                line += " "
        lines.append(line)
    return "\n".join(lines)

